<script lang="ts">
import { defineComponent, nextTick } from 'vue';
import { clearBookSources, getBook, mergeBookSources, type Book } from '../../api/books';
import type { AltSource, Chapter } from '../../api/models';
import { getChapterContent, getChapterImageUrl, getChapters, getFontUrl, listFonts, switchBookSource, type ChapterContent, type Font } from '../../api/reader';
import AppButton from '../../ui/components/AppButton.vue';
import { adjacentChapterIndex, clampProgress, normalizedScroll, resolveChapterIndex, scrollTopForProgress } from './reading-progress';
import { getProgressVersion, queueProgressWrite, setProgressVersion, waitForProgressWrites } from './progress-writer';
import { loadReaderPreferences, saveReaderPreferences, type ReaderPreferences } from './reader-preferences';
import ReaderBookmarksSheet from './ReaderBookmarksSheet.vue';
import ReaderSettingsSheet from './ReaderSettingsSheet.vue';
import ReaderSourceSheet from './ReaderSourceSheet.vue';
import ReaderTocSheet from './ReaderTocSheet.vue';

export default defineComponent({
  name: 'ReaderView', components: { AppButton, ReaderBookmarksSheet, ReaderSettingsSheet, ReaderSourceSheet, ReaderTocSheet },
  data() { return { book: null as Book | null, chapters: [] as Chapter[], content: null as ChapterContent | null, fonts: [] as Font[], currentIndex: 0, sourceUrl: '', contentSourceUrl: '', loading: true, error: '', progressError: '', sourceError: '', sourceMessage: '', switching: false, chromeVisible: true, activeSheet: '' as ''|'toc'|'settings'|'bookmarks'|'sources', preferences: loadReaderPreferences(), lastPosition: 0, restoring: false, generation: 0, progressTimer: undefined as ReturnType<typeof setTimeout>|undefined, persistence: Promise.resolve() as Promise<void>, suppressRouteLoad: false };  },
  computed: {
    bookId(): string { return String(this.$route.params.bookId || ''); },
    routeChapter(): number | undefined { const value=Number(this.$route.params.chapterIndex); return Number.isInteger(value)&&value>=0?value:undefined; },
    routePosition(): number | undefined { const value=Number(this.$route.query.position); return Number.isFinite(value)?clampProgress(value):undefined; },
    previousIndex(): number|null { return adjacentChapterIndex(this.chapters,this.currentIndex,-1); },
    nextIndex(): number|null { return adjacentChapterIndex(this.chapters,this.currentIndex,1); },
    currentTitle(): string { return this.content?.title || this.chapters.find(chapter=>chapter.index===this.currentIndex)?.title || ''; },
    fontFamily(): string { return this.preferences.fontId==='system'?'var(--font-literary)':`reader-font-${this.preferences.fontId}, var(--font-literary)`; },
    readerStyle(): Record<string,string> { return { '--reader-bg':this.preferences.background,'--reader-text':this.preferences.textColor,'--reader-size':`${this.preferences.fontSize}px`,'--reader-line':String(this.preferences.lineHeight),'--reader-weight':String(this.preferences.fontWeight),'--reader-width':`${this.preferences.pageWidth}px`,'--reader-font':this.fontFamily }; },
    recoveryNeeded(): boolean { return Boolean(this.error); },
  },
  watch: {
    '$route.fullPath'() { if (this.suppressRouteLoad) { this.suppressRouteLoad=false; return; } void this.load(); },
    preferences: { deep:true, handler(value:ReaderPreferences) { saveReaderPreferences(value); } },
  },
  async mounted() { await this.load(); void this.loadFonts(); },
  beforeUnmount() { this.generation+=1; if(this.progressTimer)clearTimeout(this.progressTimer); void this.persistProgress(); },
  methods: {
    async load() {
      const request=++this.generation; this.loading=true; this.error='';
      try { await waitForProgressWrites(this.bookId); const book=await getBook(this.bookId); if(request!==this.generation)return; this.book=book;this.sourceUrl=book.sourceUrl;setProgressVersion(this.bookId,book.stateVersion); const chapters=await getChapters(this.bookId); if(request!==this.generation)return; this.chapters=chapters; const index=resolveChapterIndex(chapters,this.routeChapter,book.durChapterIndex); if(index===null)throw new Error(this.$t('reader.errors.noReadable')); const position=this.routePosition ?? (index===book.durChapterIndex?book.durChapterPos:0); await this.loadContent(index,position,request); }
      catch(cause){if(request!==this.generation)return;this.error=cause instanceof Error?cause.message:this.$t('reader.errors.load');this.loading=false;this.chromeVisible=true;this.activeSheet='sources'}
    },
    async loadContent(index:number,position:number,request?:number) { request ??= this.generation; const content=await getChapterContent(this.bookId,index);if(request!==this.generation)return;this.currentIndex=index;this.content=content;this.contentSourceUrl=this.sourceUrl;this.lastPosition=position;this.loading=false;this.error='';await this.restore(position,request);if(this.book&&index!==this.book.durChapterIndex)await this.queueProgress(index,position);document.title=`${content.title} · ${this.book?.name || 'NovelReader'}`; },
    async restore(position:number,request:number){await nextTick();requestAnimationFrame(()=>{if(request!==this.generation)return;const host=this.$refs.scrollHost as HTMLElement|undefined;if(!host)return;this.restoring=true;host.scrollTop=scrollTopForProgress(position,host.scrollHeight,host.clientHeight);requestAnimationFrame(()=>{this.restoring=false})})},
    onScroll(){if(this.loading||this.restoring||!this.content)return;const host=this.$refs.scrollHost as HTMLElement;this.lastPosition=normalizedScroll(host.scrollTop,host.scrollHeight,host.clientHeight);if(this.progressTimer)clearTimeout(this.progressTimer);this.progressTimer=setTimeout(()=>void this.persistProgress(),600)},
    persistProgress(){if(!this.content||!this.book||this.contentSourceUrl!==this.sourceUrl)return Promise.resolve();return this.queueProgress(this.currentIndex,this.lastPosition)},
    async queueProgress(index:number,position:number){try{await queueProgressWrite(this.bookId,{sourceUrl:this.sourceUrl,chapterIndex:index,position});this.progressError=''}catch{this.progressError=this.$t('reader.errors.progress')}},
    async navigate(index:number|null,position=0){if(index===null)return;if(this.progressTimer)clearTimeout(this.progressTimer);await this.persistProgress();this.activeSheet='';const request=++this.generation;this.error='';try{await this.loadContent(index,position,request);this.suppressRouteLoad=true;await this.$router.push({name:'reader',params:{bookId:this.bookId,chapterIndex:index},query:position?{position:String(position)}:{}})}catch(cause){if(request!==this.generation)return;this.loading=false;this.error=cause instanceof Error?cause.message:this.$t('reader.errors.load');this.chromeVisible=true;this.activeSheet='sources'}},
    async captureBookmark(){const host=this.$refs.scrollHost as HTMLElement;if(!this.content||!host||this.contentSourceUrl!==this.sourceUrl)throw new Error(this.$t('reader.errors.position'));this.lastPosition=normalizedScroll(host.scrollTop,host.scrollHeight,host.clientHeight);if(this.progressTimer)clearTimeout(this.progressTimer);await this.persistProgress();const stateVersion=getProgressVersion(this.bookId);if(stateVersion===undefined)throw new Error(this.$t('reader.errors.position'));return{position:this.lastPosition,stateVersion}},
    imageUrl(index:number){return getChapterImageUrl(this.bookId,this.currentIndex,index)},
    async loadFonts(){try{this.fonts=await listFonts();for(const font of this.fonts){const family=`reader-font-${font.id}`;const face=new FontFace(family,`url(${getFontUrl(font.id)})`);void face.load().then(loaded=>document.fonts.add(loaded)).catch(()=>undefined)}}catch{/* optional */}},
    persistMatches(sources:AltSource[]){if(!this.book||!sources.length)return;this.persistence=this.persistence.then(async()=>{if(this.book)this.book=await mergeBookSources(this.book.id,sources)}).catch(cause=>{this.sourceError=cause instanceof Error?cause.message:this.$t('sourceRecovery.persistFailed')})},
    async clearAndRescan(){try{await this.persistence;if(!this.book)throw new Error(this.$t('reader.errors.load'));this.book=await clearBookSources(this.book.id);this.sourceMessage=this.$t('sourceRecovery.cleared');this.sourceError=''}catch(cause){this.sourceError=cause instanceof Error?cause.message:this.$t('sourceRecovery.clearFailed');throw cause}},
    async selectSource(source:AltSource){if(!this.book||this.switching)return;this.switching=true;this.sourceError='';this.sourceMessage='';if(this.progressTimer)clearTimeout(this.progressTimer);let switched=false;try{await this.persistProgress();await waitForProgressWrites(this.bookId);this.book=await mergeBookSources(this.book.id,[source]);const result=await switchBookSource(this.book.id,source.sourceUrl,source.bookUrl);switched=true;this.book=result.book;this.sourceUrl=result.book.sourceUrl;setProgressVersion(this.bookId,result.book.stateVersion);const chapters=await getChapters(this.bookId);this.chapters=chapters;const mapped=resolveChapterIndex(chapters,result.book.durChapterIndex,result.book.durChapterIndex);if(mapped===null)throw new Error(this.$t('reader.errors.noReadable'));this.sourceMessage=result.mapping==='title'?this.$t('sourceRecovery.switchedTitle'):this.$t('sourceRecovery.switchedIndex');this.error='';this.content=null;this.currentIndex=mapped;this.lastPosition=result.book.durChapterPos||0;if(mapped!==this.routeChapter){await this.loadContent(mapped,this.lastPosition);this.suppressRouteLoad=true;await this.$router.replace({name:'reader',params:{bookId:this.bookId,chapterIndex:mapped}})}else await this.loadContent(mapped,this.lastPosition)}catch(cause){const message=cause instanceof Error?cause.message:this.$t('sourceRecovery.switchFailed');this.sourceError=switched?this.$t('reader.errors.switchedReload',{message}):message;if(!this.content)this.error=this.sourceError}finally{this.switching=false}},
  },
});
</script>

<template><section class="reader" :style="readerStyle"><header v-show="chromeVisible" class="reader-header"><RouterLink :to="`/books/${encodeURIComponent(bookId)}`" class="back">{{ $t('reader.back') }}</RouterLink><div><strong>{{ book?.name || $t('reader.title') }}</strong><span>{{ currentTitle }}</span></div><button type="button" @click="chromeVisible=false">{{ $t('reader.hide') }}</button></header><main ref="scrollHost" class="reader-scroll" tabindex="0" @scroll.passive="onScroll" @click.self="chromeVisible=!chromeVisible"><article class="prose"><p v-if="loading && !content" class="state">{{ $t('reader.loading') }}</p><section v-else-if="error && !content" class="failure"><h1>{{ currentTitle || book?.name || $t('reader.errors.chapter') }}</h1><p role="alert">{{ error }}</p><AppButton @click="activeSheet='sources'">{{ $t('reader.recover') }}</AppButton></section><template v-else-if="content"><h1>{{ content.title }}</h1><aside v-if="error" class="content-failure" role="alert"><span>{{ error }}</span><AppButton variant="secondary" @click="activeSheet='sources'">{{ $t('reader.recover') }}</AppButton></aside><p v-if="content.offlineCopy" class="offline" role="status">{{ $t('reader.offline') }}</p><template v-if="content.blocks.length"><template v-for="(block,index) in content.blocks" :key="index"><p v-if="block.type==='text'">{{ block.text }}</p><figure v-else><img :src="imageUrl(block.index)" :alt="$t('reader.imageAlt',{title:content.title})" loading="lazy" decoding="async"></figure></template></template><p v-for="(paragraph,index) in content.blocks.length?[]:content.paragraphs" :key="index">{{ paragraph }}</p><p class="chapter-end">{{ $t('reader.chapterEnd') }}</p></template></article></main><p v-if="progressError" class="progress-error" role="status">{{ progressError }}</p><footer v-show="chromeVisible" class="reader-controls"><button :disabled="previousIndex===null" @click="navigate(previousIndex)"><span aria-hidden="true">‹</span>{{ $t('reader.previous') }}</button><button @click="activeSheet='toc'"><span aria-hidden="true">☰</span>{{ $t('reader.toc.title') }}</button><button @click="activeSheet='settings'"><span aria-hidden="true">Aa</span>{{ $t('reader.settings.title') }}</button><button @click="activeSheet='bookmarks'"><span aria-hidden="true">◇</span>{{ $t('reader.bookmarks.title') }}</button><button :class="{attention:recoveryNeeded}" @click="activeSheet='sources'"><span aria-hidden="true">↻</span>{{ $t('reader.sources.short') }}</button><button :disabled="nextIndex===null" @click="navigate(nextIndex)"><span aria-hidden="true">›</span>{{ $t('reader.next') }}</button></footer><button v-if="!chromeVisible" class="show-chrome" @click="chromeVisible=true">{{ $t('reader.show') }}</button><ReaderSettingsSheet v-if="activeSheet==='settings'" v-model="preferences" :fonts="fonts" @close="activeSheet=''" /><ReaderTocSheet v-if="activeSheet==='toc'" :chapters="chapters" :current-index="currentIndex" @open="navigate" @close="activeSheet=''" /><ReaderBookmarksSheet v-if="activeSheet==='bookmarks'&&book" :book-id="book.id" :source-url="sourceUrl" :chapter-index="currentIndex" :capture="captureBookmark" @open="navigate" @close="activeSheet=''" /><ReaderSourceSheet v-if="activeSheet==='sources'&&book" :book="{name:book.name,author:book.author}" :current-source="book.origin||book.sourceUrl" :current-source-url="book.sourceUrl" :stored-sources="book.alternateSources||[]" :switching="switching" :action-error="sourceError||error" :action-message="sourceMessage" :on-clear-and-rescan="clearAndRescan" @matches="persistMatches" @select="selectSource" @close="activeSheet=''" /></section></template>

<style scoped>.reader{position:fixed;z-index:80;inset:0;display:grid;grid-template-rows:auto minmax(0,1fr) auto;background:var(--reader-bg);color:var(--reader-text)}.reader-header{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:1rem;align-items:center;padding:max(.65rem,env(safe-area-inset-top)) max(1rem,env(safe-area-inset-right)) .65rem max(1rem,env(safe-area-inset-left));border-bottom:1px solid color-mix(in srgb,var(--reader-text) 15%,transparent);background:color-mix(in srgb,var(--reader-bg) 94%,transparent);backdrop-filter:blur(12px)}.reader-header div{min-width:0;text-align:center}.reader-header strong,.reader-header span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.reader-header span{font-size:.8rem;opacity:.7}.reader-header button,.back{min-height:2.75rem;display:inline-flex;align-items:center;border:0;padding:.5rem;background:transparent;color:inherit;text-decoration:none}.reader-scroll{min-height:0;overflow:auto;scroll-behavior:auto}.prose{width:min(var(--reader-width),calc(100% - 2rem));min-height:100%;margin:0 auto;padding:clamp(1.6rem,5vw,4rem) 0 7rem;font:var(--reader-weight) var(--reader-size)/var(--reader-line) var(--reader-font);letter-spacing:.015em}.prose h1{margin:0 0 2.5rem;text-align:center;font-size:1.55em;line-height:1.3}.prose p{margin:0 0 .85em;text-align:justify;overflow-wrap:anywhere}.prose figure{margin:1.5rem 0}.prose img{display:block;width:100%;max-height:85dvh;object-fit:contain}.state,.failure{text-align:center;padding:4rem 1rem}.failure p{text-align:center;color:var(--color-danger)}.content-failure{display:flex;align-items:center;justify-content:space-between;gap:.75rem;margin:0 0 1.5rem;padding:.75rem;border:1px solid color-mix(in srgb,var(--color-danger) 40%,transparent);border-radius:var(--radius-md);background:color-mix(in srgb,var(--color-danger) 8%,var(--reader-bg));color:var(--color-danger);font:600 .82rem var(--font-ui)}.offline{padding:.75rem;border:1px solid var(--color-warm);border-radius:var(--radius-md);color:var(--color-warm);font-family:var(--font-ui);font-size:.82rem}.chapter-end{text-align:center!important;opacity:.45;margin-top:3rem!important;font-family:var(--font-ui);font-size:.8rem}.progress-error{position:fixed;z-index:50;left:50%;bottom:5.4rem;translate:-50% 0;margin:0;padding:.5rem .8rem;border-radius:999px;background:var(--color-danger);color:white;font:600 .78rem var(--font-ui)}.reader-controls{display:grid;grid-template-columns:repeat(6,1fr);padding:.35rem max(.5rem,env(safe-area-inset-right)) max(.35rem,env(safe-area-inset-bottom)) max(.5rem,env(safe-area-inset-left));border-top:1px solid color-mix(in srgb,var(--reader-text) 15%,transparent);background:var(--reader-bg)}.reader-controls button{min-width:0;min-height:3.5rem;display:grid;place-content:center;justify-items:center;gap:.12rem;border:0;border-radius:var(--radius-md);background:transparent;color:inherit;font:600 .7rem var(--font-ui)}.reader-controls button span{height:1.25rem;display:grid;place-items:center;font-size:1rem}.reader-controls button:disabled{opacity:.3}.reader-controls .attention{color:var(--color-danger);background:color-mix(in srgb,var(--color-danger) 10%,transparent)}.show-chrome{position:fixed;z-index:45;left:50%;bottom:max(1rem,env(safe-area-inset-bottom));translate:-50% 0;min-height:2.75rem;border:1px solid color-mix(in srgb,var(--reader-text) 25%,transparent);border-radius:999px;padding:.5rem 1rem;background:color-mix(in srgb,var(--reader-bg) 90%,transparent);color:inherit}@media(max-width:36rem){.prose{width:min(var(--reader-width),calc(100% - 2rem));padding-top:2rem}.reader-controls{grid-template-columns:repeat(6,minmax(0,1fr))}.reader-controls button{font-size:.62rem}}@media(max-height:30rem) and (orientation:landscape){.reader-header{padding:.25rem 1rem}.reader-controls button{min-height:2.9rem}.prose{padding-top:1.2rem}}</style>
